import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    T = int(input_data[0])
    results = []
    idx = 1
    for _ in range(T):
        X = int(input_data[idx])
        Y = int(input_data[idx+1])
        Z = int(input_data[idx+2])
        idx += 3

        if Y >= 2 * X:
            two_packs = (Z + 1) // 2
            ans = two_packs * X
        else:
            four_packs = Z // 4
            rem = Z % 4
            if rem == 0:
                ans = four_packs * Y
            elif rem <= 2:
                ans = four_packs * Y + min(X, Y)
            else:
                ans = four_packs * Y + min(2 * X, Y)
        results.append(str(ans))
    print('\n'.join(results))

if __name__ == '__main__':
    solve()

