public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int T = sc.nextInt();
        while (T-- > 0) {
            long X = sc.nextLong();
            long Y = sc.nextLong();
            long Z = sc.nextLong();

            if (Y >= 2 * X) {
                long twoPacks = (Z + 1) / 2;
                System.out.println(twoPacks * X);
            } else {
                long fourPacks = Z / 4;
                long rem = Z % 4;
                if (rem == 0) {
                    System.out.println(fourPacks * Y);
                } else if (rem <= 2) {
                    System.out.println(fourPacks * Y + Math.min(X, Y));
                } else {
                    System.out.println(fourPacks * Y + Math.min(2 * X, Y));
                }
            }
        }
    }
}

